module fifo_depth_check #(
  parameter int DEPTH = 16
) (
  input  logic clk,
  input  logic rst_n,
  input  logic push,
  input  logic pop,
  input  logic full,
  input  logic empty
);
  // TODO: occupancy counter, then two assertions
endmodule

problems.solution:
int occ;
always @(posedge clk or negedge rst_n) begin
  if (!rst_n) occ <= 0;
  else case ({push && !full, pop && !empty})
    2'b10: occ <= occ + 1;
    2'b01: occ <= occ - 1;
    default: occ <= occ;
  endcase
end
assert property (@(posedge clk) disable iff (!rst_n) occ <= DEPTH);
assert property (@(posedge clk) disable iff (!rst_n) occ >= 0);

