module updown_counter (
  input  logic       clk,
  input  logic       rst_n,
  input  logic       en,
  input  logic       up,
  output logic [7:0] count,
  output logic       tc
);
  // TODO: counter and terminal count logic
endmodule

problems.solution:
always_ff @(posedge clk) begin
  if (!rst_n) count <= 8'h0;
  else if (en) count <= up ? count + 1'b1 : count - 1'b1;
end
assign tc = (count == 8'hFF) && up && en;

